import {createQuestExperience} from './story-view.js';
import {STORY_TITLE,CAST,objective,storyDestination,repairCost,provisionRate} from './story.js';
import {LAND,isLand,inBounds,clearSea,seaRoute,coordinates,oceanName,nauticalMiles} from './geography.js';
import {createWorld} from './world.js';
import {PORTS,RUIN,GOODS,newGame,loadGame,saveGame,trade,cargoCount} from './state.js';
const $=id=>document.getElementById(id);let storage;try{storage=localStorage;}catch{storage={getItem(){return null},setItem(){throw Error('Unavailable');}};}
let state=loadGame(storage),world;const keys=new Set();let paused=false,velocity=0,target=null,nearPort=null,activePort=null,activeTab='market',lastTime=performance.now(),elapsed=0,saveTimer=0,hudTimer=0,fireCooldown=0,pirateHull=100,pirateCooldown=0,muted=true,audioCtx=null,toastTimer,largeMap=null;const modal=$('modal');
try{world=createWorld($('world'));$('loading').style.opacity='0';setTimeout(()=>$('loading').remove(),750);}catch(err){$('loading').innerHTML='<h1>HORIZON</h1><p>The ocean needs WebGL to render.</p><p>Enable hardware acceleration in your browser, then reload.</p>';console.error(err);throw err;}
const questExperience=createQuestExperience(world.renderer,{getState:()=>state,save,toast,keys,onExit:()=>{updateHUD();$('dock').focus();},onCourse:plotStoryCourse});
function plotStoryCourse(id=storyDestination(state)){if(!id)return;if(modal.open)closeModal();const p=id==='azores'?RUIN:PORTS.find(p=>p.id===id);navigate(p.harbor.x,p.harbor.z,id==='azores'?'Azores wreck camp':p.name);}
function goAshore(place){closeModal();state.sail=0;target=null;velocity=0;questExperience.enter(place);}
function nearWreck(){return state.story.phase==='charted'&&Math.hypot(state.x-RUIN.harbor.x,state.z-RUIN.harbor.z)<1.8;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function save(){const ok=saveGame(storage,state);$('saved').textContent=ok?'Progress saved on this device':'Saving unavailable in this browser';}
function sound(freq=440,duration=.15,type='sine'){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.5,audioCtx.currentTime+duration);g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function setSail(n){state.sail=n;target=null;updateHUD();}
function navigate(x,z,label){if(!inBounds(x,z)){toast('Choose a destination within the world chart.');return;}if(isLand(x,z)){toast('Choose open water or a city’s harbor marker.');return;}const route=seaRoute({x:state.x,z:state.z},{x,z});if(!route){toast('No navigable sea route found. Choose a nearby coastal waypoint.');return;}target={x,z,label:label||'Selected waypoint',route};state.sail=1;sound(500);updateHUD();return true;}
PORTS.forEach(p=>{const b=document.createElement('button');b.className='port-label';b.setAttribute('aria-label',`Set course for ${p.name}`);b.innerHTML=`<span class="name">${p.name}</span><span class="type">${p.kind}</span><span class="pin">⚓</span>`;b.onclick=()=>{navigate(p.harbor.x,p.harbor.z,p.name);toast(`Course set for ${p.name}.`);};$('labels').appendChild(b);p.label=b;});
const ruinLabel=document.createElement('button');ruinLabel.className='port-label';ruinLabel.innerHTML='<span class="name">Azores</span><span class="type">ATLANTIC DISCOVERY</span><span class="pin">◇</span>';ruinLabel.onclick=()=>navigate(RUIN.harbor.x,RUIN.harbor.z,'Azores Observatory');$('labels').appendChild(ruinLabel);
$('world').addEventListener('pointerdown',e=>{if(e.button!==0||paused||modal.open||questExperience.dialogueOpen)return;if(questExperience.room.active){questExperience.room.click(e.clientX,e.clientY);return;}const p=world.pick(e.clientX,e.clientY);if(p)navigate(p.x,p.z);});$('world').addEventListener('wheel',e=>{e.preventDefault();if(!questExperience.room.active)world.zoom(e.deltaY);},{passive:false});
document.querySelectorAll('[data-sail]').forEach(b=>b.onclick=()=>setSail(Number(b.dataset.sail)));document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});
function openModal(){keys.clear();modal.showModal();}function closeModal(){modal.close();activePort=null;largeMap=null;save();}
$('close-modal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});modal.addEventListener('close',()=>{keys.clear();activePort=null;largeMap=null;});
function pause(){paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume game':'Pause game');toast(paused?'Voyage paused.':'Back at the helm.');}$('pause').onclick=pause;
function enterPort(){if(nearWreck()){state.sail=0;target=null;velocity=0;questExperience.enter('azores');return;}if(!nearPort){toast('Sail closer to a harbor to enter port.');return;}activePort=nearPort;state.sail=0;target=null;velocity=0;activeTab='market';if(!state.discovered.includes(activePort.id)){state.discovered.push(activePort.id);state.log.push(`Day ${Math.floor(state.time/1440)+1} — Arrived at ${activePort.name}.`);}renderPort();openModal();sound(660);save();}
$('dock').onclick=enterPort;
function renderPort(){const p=activePort;if(!p)return;const content=$('modal-content');content.innerHTML=`<div class="modal-eyebrow">⚓ ${p.kind}</div><h2>${p.name}</h2><p class="intro">${p.description}</p>${['lisbon','london'].includes(p.id)?`<div class="shore-card"><div><small>GO ASHORE</small><h3>${p.id==='lisbon'?'The Lantern & Tide':'The Merchant Guild'}</h3><p>${p.id==='lisbon'?'A lantern in the window. A captain missing at sea.':'Ledgers, sea charts, and a familiar silver emblem.'}</p></div><button id="go-ashore" class="action-btn">Enter ${p.id==='lisbon'?'tavern':'guild'} ↗</button></div>`:''}<div class="port-tabs"><button data-tab="market" class="${activeTab==='market'?'active':''}">Marketplace</button><button data-tab="shipyard" class="${activeTab==='shipyard'?'active':''}">Harbor services</button></div><div id="port-body"></div><div class="cargo-total"><span>Hold: ${cargoCount(state)} / 40 crates</span><span>◈ ${state.gold.toLocaleString()} gold</span></div>`;const shore=$('go-ashore');if(shore)shore.onclick=()=>goAshore(p.id);content.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderPort();});const body=$('port-body');if(activeTab==='market'){body.innerHTML='<div class="trade-row" style="padding-top:0;color:#95b5af"><span>COMMODITY</span><span>BUY</span><span>SELL</span><span></span><span></span></div>'+GOODS.map(g=>`<div class="trade-row"><div><b>${g.icon} &nbsp;${g.name}</b><small>${state.cargo[g.id]} in hold</small></div><span class="price">${p.prices[g.id]}</span><span>${Math.floor(p.prices[g.id]*.85)}</span><button data-buy="${g.id}" ${state.gold<p.prices[g.id]||cargoCount(state)>=40?'disabled':''}>Buy</button><button data-sell="${g.id}" ${!state.cargo[g.id]?'disabled':''}>Sell</button></div>`).join('');body.querySelectorAll('[data-buy],[data-sell]').forEach(b=>b.onclick=()=>{const side=b.dataset.buy?'buy':'sell';const r=trade(state,p,b.dataset.buy||b.dataset.sell,side);toast(r.message);if(r.ok)sound(side==='buy'?650:850);renderPort();updateHUD();save();});}else{const repair=repairCost(state);body.innerHTML=`<div class="service"><div><b>Restock provisions</b><p>10 days of food and fresh water.</p></div><button class="action-btn" id="resupply" ${state.gold<60||state.supplies>=60?'disabled':''}>60 gold</button></div><div class="service"><div><b>Repair The Wayfarer</b><p>Hull integrity: ${Math.floor(state.hull)}%</p></div><button class="action-btn" id="repair" ${repair===0||state.gold<repair?'disabled':''}>${repair||'Fully repaired'}${repair?' gold':''}</button></div>`;$('resupply').onclick=()=>{if(state.gold<60||state.supplies>=60)return;state.gold-=60;state.supplies=Math.min(60,state.supplies+10);toast('Provisions replenished.');renderPort();updateHUD();save();};$('repair').onclick=()=>{if(state.gold<repair)return;state.gold-=repair;state.hull=100;toast('Your ship is ready for the open sea.');renderPort();updateHUD();save();};}}
function openCargo(){$('modal-content').innerHTML=`<div class="modal-eyebrow">THE WAYFARER · LIGHT CARAVEL</div><h2>The cargo hold</h2><p class="intro">Every crate is a possibility. Trade at the harbors to turn a little gold into a fortune.</p>${GOODS.map(g=>`<div class="service"><div><b>${g.icon} &nbsp; ${g.name}</b><p>${g.desc}</p></div><b>${state.cargo[g.id]} crates</b></div>`).join('')}<div class="cargo-total"><span>${cargoCount(state)} / 40 crates loaded</span><span>◈ ${state.gold.toLocaleString()} gold</span></div>`;openModal();}$('cargo').onclick=openCargo;
function openJournal(){$('modal-content').innerHTML=`<div class="modal-eyebrow">CAPTAIN’S JOURNAL</div><h2>Stories of the sea</h2>${questExperience.journal()}<div class="journal-entry"><small>${state.quest>=2?'COMPLETED · +500 GOLD':'CHAPTER I · A MERCHANT’S FIRST VOYAGE'}</small><h3>The saffron route</h3><p>Buy 3 crates of saffron in Lisbon for 80 gold each. Sail north to London and sell them for 123 gold each. Deliver all 3 to receive a 500 gold commission.</p><p>Delivered: ${state.delivered||0} / 3 crates</p></div><div class="journal-entry"><small>${state.quest===3?'DISCOVERED · +750 GOLD':'CHAPTER II · SECRETS OF THE ISLES'}</small><h3>The Azores Observatory</h3><p>After completing the saffron route, sail west across the Atlantic to the Azores. Approach the discovery marker to discover the ancient observatory and claim a 750 gold exploration reward.</p></div><h3>Voyage log</h3>${state.log.slice(-8).reverse().map(s=>`<p class="intro" style="margin:10px 0">${s}</p>`).join('')}`;openModal();questExperience.bindJournal();}$('journal').onclick=openJournal;
function drawMap(canvas,large=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,scale=Math.min(w/380,h/160);const to=(x,z)=>[w/2+x*scale,h/2+(z+6.5)*scale];ctx.clearRect(0,0,w,h);ctx.strokeStyle='#86b6a62b';ctx.lineWidth=.6;for(let x=-180;x<=180;x+=30){ctx.beginPath();ctx.moveTo(...to(x,-78));ctx.lineTo(...to(x,65));ctx.stroke();}for(let z=-60;z<=60;z+=30){ctx.beginPath();ctx.moveTo(...to(-180,z));ctx.lineTo(...to(180,z));ctx.stroke();}ctx.fillStyle='#82976e';ctx.strokeStyle='#c4b781';for(const rings of LAND){ctx.beginPath();for(const ring of rings){ring.forEach(([x,z],i)=>{const p=to(x,z);i?ctx.lineTo(...p):ctx.moveTo(...p);});ctx.closePath();}ctx.fill('evenodd');ctx.stroke();}if(target){ctx.strokeStyle='#e4c68e';ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(...to(state.x,state.z));for(const p of target.route)ctx.lineTo(...to(p.x,p.z));ctx.stroke();ctx.setLineDash([]);}for(const p of PORTS){const [x,y]=to(p.x,p.z);ctx.fillStyle=nearPort?.id===p.id?'#fff7ce':'#dec28b';ctx.beginPath();ctx.arc(x,y,large?3.5:1.6,0,Math.PI*2);ctx.fill();if(large&&['lisbon','london','cape-town','havana','rio','bangkok','nagasaki','kozhikode'].includes(p.id)){ctx.font='12px Georgia';ctx.textAlign='left';ctx.fillStyle='#fff1c6';ctx.fillText(p.name,x+6,y-5);}}const [sx,sy]=to(state.x,state.z);ctx.save();ctx.translate(sx,sy);ctx.rotate(-state.heading);ctx.fillStyle='#fff4c6';ctx.shadowColor='#fff4c3';ctx.shadowBlur=7;ctx.beginPath();ctx.moveTo(0,6);ctx.lineTo(-3.5,-4);ctx.lineTo(3.5,-4);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#b4cbbd';ctx.font='10px Georgia';ctx.textAlign='center';ctx.fillText('N',w/2,12);}
function openChart(){$('modal-content').innerHTML='<div class="modal-eyebrow">WORLD ATLAS · 20 PORT CITIES</div><h2>The world is your horizon</h2><p class="intro">Select a city to chart an ocean route. Coastlines and city coordinates are geographic; travel time and markets are simplified for play.</p><canvas id="large-map" class="chart-large" width="900" height="400" aria-label="Interactive world map with real port cities"></canvas><div class="port-directory">'+PORTS.map(p=>`<button class="action-btn" data-port="${p.id}"><b>${p.name}</b><small>${p.kind}</small></button>`).join('')+'</div><p class="map-source">Coastlines: Natural Earth · Public domain. Harbor approaches are offset into navigable water.</p>';openModal();largeMap=$('large-map');drawMap(largeMap,true);document.querySelectorAll('[data-port]').forEach(b=>b.onclick=()=>{const p=PORTS.find(p=>p.id===b.dataset.port);navigate(p.harbor.x,p.harbor.z,p.name);if(target)closeModal();});largeMap.onclick=e=>{const rect=largeMap.getBoundingClientRect(),xx=(e.clientX-rect.left)*largeMap.width/rect.width,zz=(e.clientY-rect.top)*largeMap.height/rect.height;const scale=Math.min(largeMap.width/380,largeMap.height/160),x=(xx-largeMap.width/2)/scale,z=(zz-largeMap.height/2)/scale-6.5;const p=[...PORTS].sort((a,b)=>Math.hypot(a.x-x,a.z-z)-Math.hypot(b.x-x,b.z-z))[0];if(Math.hypot(p.x-x,p.z-z)<5){navigate(p.harbor.x,p.harbor.z,p.name);}else navigate(x,z);if(target)closeModal();};}$('chart').onclick=$('chart-nav').onclick=$('minimap').onclick=openChart;
$('ship-info').onclick=()=>{$('modal-content').innerHTML=`<div class="modal-eyebrow">YOUR FLAGSHIP</div><h2>The Wayfarer</h2><p class="intro">A nimble two-masted caravel, made for coastal trading and bold journeys into unknown waters.</p><div class="service"><span>Hull integrity</span><b>${Math.floor(state.hull)}%</b></div><div class="service"><span>Crew aboard</span><b>24 sailors</b></div><div class="service"><span>Cargo capacity</span><b>${cargoCount(state)} / 40 crates</b></div><div class="service"><span>Companion</span><b>${state.story.companion?CAST[state.story.companion].name:'No companion yet'}</b></div><div class="service"><span>Armament</span><b>6 light cannons</b></div><p class="intro" style="margin-top:20px">Press Space to fire when a pirate is within 300 nautical miles. Repairs and provisions are available at every harbor.</p>`;openModal();};
function settings(){$('modal-content').innerHTML=`<div class="modal-eyebrow">VOYAGE OPTIONS</div><h2>Make yourself at home</h2><div class="setting"><label for="audio">Sound effects</label><input id="audio" type="checkbox" ${!muted?'checked':''}></div><div class="setting"><label for="quality">High resolution & shadows</label><input id="quality" type="checkbox" ${highQuality?'checked':''}></div><p class="intro">W / S to raise or lower sail. A / D to steer. Click open water to navigate automatically. Scroll to zoom. E enters a nearby port. J opens your journal; M opens the chart. P pauses the voyage.</p><p class="intro">Your voyage saves automatically in this browser. Closing a panel resumes sailing.</p><button id="restart" class="action-btn">Start a new voyage</button>`;openModal();$('audio').onchange=e=>{muted=!e.target.checked;sound(660);};$('quality').onchange=e=>{highQuality=e.target.checked;world.setQuality(highQuality);};$('restart').onclick=()=>{$('modal-content').innerHTML='<div class="modal-eyebrow">NEW VOYAGE</div><h2>Leave this story behind?</h2><p class="intro">This will replace your saved voyage, gold, cargo, and discoveries on this device.</p><button id="confirm-restart" class="action-btn">Begin a new voyage</button> <button id="cancel-restart" class="action-btn">Keep my voyage</button>';$('confirm-restart').onclick=()=>{state=newGame();target=null;velocity=0;pirateHull=100;world.npc.visible=true;closeModal();updateHUD();toast('A fresh start. Fair winds, Captain.');};$('cancel-restart').onclick=settings;};}let highQuality=true;$('settings').onclick=settings;
function fire(){if(paused||modal.open||questExperience.room.active)return;if(fireCooldown>0){toast('The crew is reloading the cannons.');return;}fireCooldown=4;world.burst(state.x+Math.cos(state.heading)*1.5,state.z-Math.sin(state.heading)*1.5,'#edd0a1');sound(75,.7,'sawtooth');const d=Math.hypot(state.x-world.npc.position.x,state.z-world.npc.position.z);if(d<5&&pirateHull>0){pirateHull-=34;world.burst(world.npc.position.x,world.npc.position.z,'#c48755');if(pirateHull<=0){state.gold+=250;state.log.push('Defeated a corsair and collected a 250 gold bounty.');world.npc.visible=false;toast('Corsair defeated! +250 gold bounty.');save();}else toast(`Direct hit! Corsair hull: ${Math.max(0,pirateHull)}%.`);}else toast('Broadside fired. No hostile ship within range.');}$('fire').onclick=fire;
addEventListener('keydown',e=>{if(questExperience.key(e))return;if(modal.open)return;const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();keys.add(key);if(e.repeat)return;if(key==='e')enterPort();if(key==='c')openCargo();if(key==='m')openChart();if(key==='j')openJournal();if(key==='p'||key==='escape')pause();if(key===' ')fire();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{keys.clear();lastTime=performance.now();if(document.hidden)save();});
function updateHUD(){$('gold').textContent=Math.floor(state.gold).toLocaleString();$('provisions').textContent=Math.ceil(state.supplies);$('hull-label').textContent=Math.floor(state.hull)+'% hull';$('hull-bar').style.width=state.hull+'%';$('hull-bar').style.background=state.hull<35?'#d38b69':'#9bbda0';$('speed').textContent=(velocity*2.2).toFixed(1);$('sail-state').textContent=paused?'VOYAGE PAUSED':state.sail===0?'ANCHOR LOWERED':target?'COURSE PLOTTED':state.sail<1?'HALF SAIL':'FULL SAIL';document.querySelectorAll('[data-sail]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.sail)===state.sail));const day=Math.floor(state.time/1440)+1,h=Math.floor(state.time%1440/60),m=Math.floor(state.time%60);$('date').textContent=`Day ${day} · ${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;$('needle').style.transform=`rotate(${-state.heading*180/Math.PI}deg)`;$('coordinates').textContent=coordinates(state.x,state.z);$('dock').disabled=!nearPort&&!nearWreck();$('dock').innerHTML=nearPort?'<span>⚓</span> Enter port <kbd>E</kbd>':'<span>⚓</span> At sea';if(nearWreck())$('dock').innerHTML='◇ Land at wreck camp <kbd>E</kbd>';$('destination-status').textContent=target?`Sailing to ${target.label} · ${Math.ceil(target.route.reduce((v,p,i)=>v+nauticalMiles(i?target.route[i-1]:state,p),0))} nm`:'';$('fire').style.opacity=fireCooldown>0?'.5':'1';if(state.quest===0){$('quest-text').textContent='Buy 3 saffron in Lisbon and deliver it to London.';$('quest-step').textContent='A merchant’s first voyage';$('quest-hint').textContent=`Saffron aboard: ${state.cargo.saffron} / 3`;}else if(state.quest===1){$('quest-text').textContent='Sail north to London. Sell 3 crates of saffron for a 500 gold commission.';$('quest-step').textContent='Deliver the precious cargo';$('quest-hint').textContent=`Delivered: ${state.delivered||0} / 3 crates`;}else if(state.quest===2){$('quest-text').textContent='Seek the Azores west of Lisbon. Approach the discovery marker.';$('quest-step').textContent='The Azores Observatory';$('quest-hint').textContent='Discovery reward: 750 gold';}else{$('quest-text').textContent='A new trade route. An ancient discovery. The isles are yours to explore.';$('quest-step').textContent='A captain in your own right';$('quest-hint').textContent='Continue trading and exploring';}$('quest-stage').textContent='✧';document.querySelector('.quest h2').textContent=STORY_TITLE;$('quest-text').textContent=objective(state);$('quest-step').textContent=state.story.phase==='complete'?'A promise kept':'Follow the captain’s trail';$('quest-hint').textContent=state.story.phase==='rumor'?'Enter Lisbon → Enter tavern':state.story.phase==='complete'?'Companion aboard':'Open journal to chart your next destination';}
let lastLocation='';function simulation(dt){fireCooldown=Math.max(0,fireCooldown-dt);pirateCooldown=Math.max(0,pirateCooldown-dt);if(keys.has('w')||keys.has('arrowup')){state.sail=1;target=null;}if(keys.has('s')||keys.has('arrowdown')){state.sail=0;target=null;}if(keys.has('a')||keys.has('arrowleft')){state.heading+=dt*1.1;target=null;}if(keys.has('d')||keys.has('arrowright')){state.heading-=dt*1.1;target=null;}
const wanted=state.sail*2.5*(state.supplies>0?1:.4);velocity+=(wanted-velocity)*(1-Math.exp(-dt*1.6));let nx=state.x,nz=state.z;if(target){const next=target.route[0],dx=next.x-state.x,dz=next.z-state.z,d=Math.hypot(dx,dz);state.heading=Math.atan2(dx,dz);const step=Math.min(d,velocity*dt);nx+=Math.sin(state.heading)*step;nz+=Math.cos(state.heading)*step;if(d<=step+.001){target.route.shift();if(!target.route.length){toast(`Arrived at ${target.label}.`);target=null;state.sail=0;velocity=0;}}}else{nx+=Math.sin(state.heading)*velocity*dt;nz+=Math.cos(state.heading)*velocity*dt;}
if(!inBounds(nx,nz)||!clearSea({x:state.x,z:state.z},{x:nx,z:nz})){if(velocity>.2)toast('Coastline ahead. Choose a harbor or turn toward open water.');state.sail=0;velocity=0;target=null;}else{state.x=nx;state.z=nz;}state.time+=dt*10;state.supplies=Math.max(0,state.supplies-dt/360*provisionRate(state));nearPort=PORTS.find(p=>Math.hypot(state.x-p.harbor.x,state.z-p.harbor.z)<1.8)||null;const ocean=oceanName(state.x,state.z),location=nearPort?.name||ocean;if(location!==lastLocation){lastLocation=location;$('location-name').textContent=location;$('location-desc').textContent=nearPort?nearPort.kind+' · Harbor approach':coordinates(state.x,state.z)+' · Open water';}
if(state.quest===2&&Math.hypot(state.x-RUIN.harbor.x,state.z-RUIN.harbor.z)<2){state.quest=3;state.gold+=750;state.discovered.push('observatory');state.log.push('Discovered the fictional lost observatory in the Azores. Earned 750 gold.');toast('Discovery! Azores Observatory · +750 gold');sound(880,.8);save();}const pd=Math.hypot(state.x-world.npc.position.x,state.z-world.npc.position.z);if(pd<4&&pirateHull>0&&pirateCooldown===0){pirateCooldown=6;state.hull=Math.max(0,state.hull-8);world.burst(state.x,state.z,'#d7d9c4');toast('Corsair attack! Press Space to return fire, or sail away.');if(state.hull<=0){state.hull=60;state.gold=Math.max(0,state.gold-200);state.x=PORTS[0].harbor.x;state.z=PORTS[0].harbor.z;state.sail=0;velocity=0;target=null;toast('Rescued and returned to Lisbon. Repairs cost up to 200 gold.');save();}}}
